using System;
using System.Collections.Generic;
using System.Drawing;
using System.Globalization;
using System.Linq;
using System.Text;
using QRCoder;
using Telemart.Client.Core.Helpers;
using Telemart.Client.Helpers;
using Telemart.Client.TransferObjects;

namespace Telemart.Client.Business.Tag
{
    public sealed class DefaultTagPrinter : TagPrinterBase
    {
        public DefaultTagPrinter(string header, double templateWidth, double templateHeight)
            : base(header, templateWidth, templateHeight)
        {
        }

        protected override string BuildHtml(IReadOnlyCollection<TagPrintInfo> tagPrintInfos)
        {
            StringBuilder html = new StringBuilder();

            html.AppendLine($@"<html><head><meta http-equiv=""Content-Type"" content=""text/html; charset=UTF-8"">
<style>
a {{
    display: none;
}}

div.product_name {{
    font-size: 91%;
    font-weight: bold;
    text-align: center;
    height: 90px;
  overflow: hidden ;
  }}
  
  div.price_tag {{
    font-family: Tahoma, sans-serif;
    border: 1px solid black;
    position: relative;
    margin: 0px;
    padding: 0px;
    float: left;
    width: 6.5cm;
    height: 12cm;
    page-break-inside: avoid;
    overflow: hidden;}}

div.title {{
    font-size: 11px;
    background-color: #DDDDDD;
    text-align: center;
  border-bottom: 1px solid black;}}

div.product_name {{
    font-size: 70%;
    font-weight: bold;
    text-align: left;
    height: 90px;
  overflow: hidden;
width: 149px;
  padding-left:5px;
}}

 div.footer {{
                border-top: 1px solid black;
            font-size: 18px;
            text-align: center;
            white-space: nowrap;
            overflow: hidden;
            background-color: #DDDDDD;
        }}

div.qr {{
    height: 90px;
    position: absolute;
    left: 156px;
  top: 14px;}}

div.code {{
  position: absolute;
  bottom: 349px;
  font-size: 10px;
padding: 9px 0px 2px 2px;
z-index: 1;
left: 3px;}}

td.header {{
    font-weight: bold;
    background-color: #CCCCCC;
    text-align: left;
    padding: 3px 3px;
}}

tbody{{
      display: table-row-group;
    vertical-align: middle;
    border-color: inherit;
}}

table{{
    border-top: 1px solid black;
    border-collapse: collapse;
    margin: 0px;
    padding: 1px;
    width: 100%;
    max-height: 13cm;
}}

     div.promo-item-name-text {{
                    margin-left: 5px;
        }}
        
        div.promo-item-name {{
                    border-top: 1px solid black;
            white-space: nowrap;
            overflow: hidden;
            background-color: #DDDDDD;
            width: 100%;
            font-size: 13px;
        }}
        
        div.promo-item {{
                    overflow: hidden;
            background-color: white;
            margin: 2 10 2 10;
        }}

tr td{{
      font-size: 10px;
    font-family: Tahoma, sans-serif;
    border-color: black;
    padding-left: 3px;
}}

</style>
</head>
<body>
 ");
            foreach (TagPrintInfo tagPrintInfo in tagPrintInfos)
            {
                html.AppendLine($@"
                <div class=""price_tag"">
                  <div class=""title"">TELEMART.UA</div>
                  <div class=""product_name"">{Helper.GetMultiLanguageValue(tagPrintInfo.ProductName, tagPrintInfo.ProductNameUkr, tagPrintInfo.LanguageId)}</div>");

                if (tagPrintInfo.Promo != null)
                {
                    if (tagPrintInfo.Promo.TagDescription != null && tagPrintInfo.Promo.TagDescriptionUkr != null)
                    {
                        html.AppendLine($@"<div class=""promo-item-name"" style=""display:inline-block;"">
                        <div class=""promo-item-name-text""> <span>{Helper.GetMultiLanguageValue("Детали акции", "Деталі акції", tagPrintInfo.LanguageId)}</span> </div>
                        </div>
                        <div class=""promo-item"" style=""font-size: 12;"">
                        <span>{Helper.GetMultiLanguageValue(tagPrintInfo.Promo.TagDescription, tagPrintInfo.Promo.TagDescriptionUkr, tagPrintInfo.LanguageId)}</span>
                        </div>");

                        html.AppendLine($@"<div class=""promo-item-name"" style=""display:inline-block;"">
                        <div class=""promo-item-name-text"">  <span>{Helper.GetMultiLanguageValue("Дата окончания", "Дата закінчення", tagPrintInfo.LanguageId)}</span> </div>
                        </div>
                        <div class=""promo-item"" style=""font-size: 13; text-align: center;"">
                        <span>{tagPrintInfo.Promo.DateEnd:dd.MM.yyyy}</span>
                        </div>");
                    }
                }

                if (tagPrintInfo.Features.Any())
                {
                    html.AppendLine(@"<table class=""table""><tbody>");

                    foreach (ProductFeatureGroupDto feature in tagPrintInfo.Features.Where(x => x.Attributes.Any(y => !string.IsNullOrWhiteSpace(Helper.GetMultiLanguageValue(y.Name, y.NameUkr, tagPrintInfo.LanguageId)))))
                    {
                        html.AppendLine($@"<tr> 

                        <td class =""header"" colspan =""2"">{Helper.GetMultiLanguageValue(feature.Name, feature.NameUkr, tagPrintInfo.LanguageId)}</td> ");

                        foreach (ProductFeatureDto attribute in feature.Attributes.Where(y => !string.IsNullOrWhiteSpace(Helper.GetMultiLanguageValue(y.Name, y.NameUkr, tagPrintInfo.LanguageId))
                                                                                              && !string.IsNullOrWhiteSpace(Helper.GetMultiLanguageValue(y.Value, y.ValueUkr, tagPrintInfo.LanguageId))))
                        {
                            html.AppendLine($@"
                              <tr>
                                 <td width=""60%"">{Helper.GetMultiLanguageValue(attribute.Name, attribute.NameUkr, tagPrintInfo.LanguageId)}</td>
                                 <td>{Helper.GetMultiLanguageValue(attribute.Value, attribute.ValueUkr, tagPrintInfo.LanguageId)}</td>
                              </tr>");
                        }

                        html.AppendLine(@"</tr>");
                    }

                    html.AppendLine(@"</tbody> </table>");
                }

                html.AppendLine($@"       
                          <div class=""code"">{tagPrintInfo.ProductId}<span style=""padding-left:50px"">{DateTime.Now: dd.MM.yy hh:mm}</span></div>
                          <div class=""qr""> <img height = ""90"" src=""{GetQRCodeImageDataBase64($"{Helper.GetMultiLanguageValue(tagPrintInfo.Link, tagPrintInfo.LinkUkr, tagPrintInfo.LanguageId)}?utm_source=showroom&utm_medium=price")}"">  </div>
                          
 <div style=""position: absolute; bottom: 0; width: 6.5cm; background: white;"">
                    <div class=""footer"" style=""height:27px;"">
                    <div style=""display: inline-block; float: left; {(tagPrintInfo.ShowPricePrev ? "border-right: 1px solid black;" : string.Empty)} height:36px; background-color: white;"">
                    <div style=""text-decoration: line-through; {(tagPrintInfo.ShowPricePrev ? "padding: 3 10;" : string.Empty)} height: 24px; font-size: 15px;""> {(tagPrintInfo.ShowPricePrev ? $"{tagPrintInfo.ProductPricePrev.ToString(CultureInfo.CurrentUICulture)}&nbsp;грн" : string.Empty)} </div>
                    </div>
                    <div style=""display:inline-block; width:40%; font-weight: bold;"">
                    <span>  {tagPrintInfo.ProductPrice.ToString(CultureInfo.CurrentUICulture)}&nbsp;грн</span>
                    </div>
                    </div>
                    <div class=""bonus-footer"">
                    <div style=""width:100%; border-top: 1px solid black; font-size: 13px; text-align: center;background-color: white; margin-bottom: 2px;  {(tagPrintInfo.BonusAmount.HasValue && tagPrintInfo.BonusAmount.Value > 0 ? string.Empty : " display: none;")}"">
                    <div style=""display: inline-block; vertical-align: bottom;"">
                    <img src=""data:image/png;base64,
                            AgICAgICAgICAKICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgIC
""
                alt=""◉"" width=""14px"" height=""14px"">
                    </div>
                    <div style=""display: inline-block;"">
                    <div><span> +{tagPrintInfo.BonusAmount?.ToString()} {Helper.GetMultiLanguageValue($"{WordEndingHelper.GetWordByNumber(tagPrintInfo.BonusAmount is null || tagPrintInfo.BonusAmount.Value == 0 ? 1 : tagPrintInfo.BonusAmount.Value, "бонус", "бонуса", "бонусов")} на счет", $"{WordEndingHelper.GetWordByNumber(tagPrintInfo.BonusAmount is null || tagPrintInfo.BonusAmount.Value == 0 ? 1 : tagPrintInfo.BonusAmount.Value, "бонус", "бонуса", "бонусів")} на рахунок", tagPrintInfo.LanguageId)}</span></div>
                    </div>
                    </div>
                    </div>
                    </div>
                      </div>
                     </div>
                    </div>
                   </div>
                  </div>
                 </div>");
            }

            html.AppendLine(@"</body></html>");

            string htmlString = html.ToString();

            return htmlString;
        }

        private static string GetQRCodeImageDataBase64(string link)
        {
            using QRCodeGenerator qrGenerator = new QRCodeGenerator();
            using QRCodeData qrCodeData = qrGenerator.CreateQrCode(link, QRCodeGenerator.ECCLevel.Q);
            using Base64QRCode qrCode = new Base64QRCode(qrCodeData);

            return $"data:image/Jpeg;base64,{qrCode.GetGraphic(10, Color.Black, Color.White, imgType: Base64QRCode.ImageType.Jpeg)}";
        }
    }
}